    assert Arrays.equals(solution.toGoatLatin("Hello world"), elloHmaa orldwmaaa);
    assert Arrays.equals(solution.toGoatLatin("Python is great"), ythonPmaa ismaaa reatgmaaaa);
    assert Arrays.equals(solution.toGoatLatin("This is a test"), hisTmaa ismaaa amaaaa esttmaaaaa);
    assert Arrays.equals(solution.toGoatLatin("Hello World"), elloHmaa orldWmaaa);
