    assert Arrays.equals(solution.toGoatLatin("Programming is fun"), rogrammingPmaa ismaaa unfmaaaa);
    assert Arrays.equals(solution.toGoatLatin("Every vowel example"), Everymaa owelvmaaa examplemaaaa);
    assert Arrays.equals(solution.toGoatLatin("hello world"), ellohmaa orldwmaaa);
